using DisputePortal.Domain.Common;

namespace DisputePortal.Domain.Disputes;

/// <param name="Id">Generated by the client when the form opens and reused on every retry: the idempotency key (ADR-007).</param>
/// <param name="DisputedAmount">The whole transaction amount, or part of it; eligibility has already checked the bounds.</param>
public sealed record DisputeSubmission(Guid Id, Guid TransactionId, Guid CustomerId, string ReasonCode, string Description, Money DisputedAmount);
